/* -------------------------------------------------- worker definition form */

.worker-dialog .dialog-header .eyebrow {
  display: block;
  width: fit-content;
  min-height: 0;
  padding: 0;
  color: var(--mc-text-dim);
  background: transparent;
  border: 0;
  border-radius: 0;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: .12em;
  line-height: 1.2;
}
.worker-dialog .worker-dialog-header-actions {
  align-items: center;
  gap: var(--mc-space-2);
}
.worker-dialog .worker-dialog-ai {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  gap: var(--mc-space-1);
  padding: 0 var(--mc-space-2);
  color: var(--mc-text-muted);
  background: transparent;
  border: 1px solid var(--mc-hairline);
  border-radius: var(--mc-radius-sm);
  font-size: 10px;
  font-weight: 560;
  transition: color var(--mc-motion-fast), background var(--mc-motion-fast), border-color var(--mc-motion-fast);
}
.worker-dialog .worker-dialog-ai > span {
  color: var(--mc-ai);
  font: 750 9px/1 var(--mc-font-mono);
}
.worker-dialog .worker-dialog-ai:hover {
  color: var(--mc-text);
  background: var(--mc-surface-2);
  border-color: var(--mc-border);
}
.worker-dialog .worker-dialog-guide {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--mc-space-2);
  padding: var(--mc-space-3) var(--mc-space-4);
  border-bottom: 1px solid var(--mc-hairline);
}
.worker-dialog .worker-dialog-guide > div {
  display: grid;
  min-width: 0;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: start;
  gap: var(--mc-space-2);
}
.worker-dialog .worker-dialog-guide > div > b {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  color: var(--mc-accent-strong);
  background: var(--mc-accent-soft);
  border: 1px solid var(--mc-accent-line);
  border-radius: var(--mc-radius-pill);
  font: 700 10px/1 var(--mc-font-mono);
}
.worker-dialog .worker-dialog-guide > div > span {
  display: grid;
  min-width: 0;
  gap: 3px;
}
.worker-dialog .worker-dialog-guide strong {
  color: var(--mc-text-soft);
  font-size: 10.5px;
  line-height: 1.3;
}
.worker-dialog .worker-dialog-guide small {
  color: var(--mc-text-dim);
  font-size: 9.5px;
  line-height: 1.45;
}
.worker-dialog .dialog-body {
  padding-bottom: calc(var(--mc-space-8) + var(--mc-space-2));
  -webkit-mask-image: linear-gradient(to bottom, black 0, black calc(100% - 24px), transparent 100%);
  mask-image: linear-gradient(to bottom, black 0, black calc(100% - 24px), transparent 100%);
}
.worker-dialog .worker-template-section {
  min-width: 0;
  padding: var(--mc-space-4);
  border-color: var(--mc-hairline);
}
.worker-dialog .worker-template-card {
  min-width: 0;
  padding: var(--mc-space-3);
}
.worker-dialog .worker-template-card code {
  display: block;
  width: 100%;
  overflow: hidden;
  white-space: nowrap;
  word-break: normal;
  overflow-wrap: normal;
  text-overflow: ellipsis;
}
.worker-dialog .worker-form-heading {
  padding-top: var(--mc-space-4);
  border-top: 1px solid var(--mc-hairline);
  border-bottom-color: var(--mc-hairline);
}
.worker-dialog .worker-form > :is(.form-check, .terminal-toggle-card) {
  border-color: var(--mc-hairline);
}

@media (max-width: 760px) {
  .worker-dialog .worker-dialog-guide { grid-template-columns: 1fr; }
  .worker-dialog .worker-dialog-ai { width: 28px; justify-content: center; overflow: hidden; white-space: nowrap; }
  .worker-dialog .worker-dialog-ai > span { flex: 0 0 auto; }
}

