  border: 1px solid var(--mc-border) !important;
  border-radius: 8px !important;
}
#root#root .shell .mc-gs-recipe.tone-crit { border-color: color-mix(in srgb, var(--mc-danger) 26%, var(--mc-border)) !important; }
#root#root .shell .mc-gs-recipe.tone-ok { border-color: color-mix(in srgb, var(--mc-accent) 26%, var(--mc-border)) !important; }
#root#root .shell .mc-gs-recipe-head { grid-area: head; display: flex; align-items: baseline; gap: 8px; min-width: 0; }
#root#root .shell .mc-gs-recipe-head strong {
  overflow: hidden;
  font-size: 12.5px; font-weight: 600; letter-spacing: -.01em;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-gs-recipe-state {
  flex: 0 0 auto;
  color: var(--mc-text-dim);
  font-size: 9.5px; font-weight: 600; letter-spacing: .04em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
#root#root .shell .mc-gs-recipe-state.tone-ok { color: var(--mc-accent); }
#root#root .shell .mc-gs-recipe-state.tone-warn { color: var(--mc-warning); }
#root#root .shell .mc-gs-recipe-state.tone-crit { color: var(--mc-danger); }
#root#root .shell .mc-gs-recipe-chain {
  grid-area: chain;
  overflow: hidden;
  color: var(--mc-text-muted); font-size: 11px;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-gs-recipe-run {
  grid-area: action;
  min-height: 28px; padding: 0 12px;
  color: var(--mc-text-soft); background: var(--mc-surface-2);
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-sm);
  box-shadow: var(--mc-raise-1);
  font-size: 11px; font-weight: 500; white-space: nowrap; cursor: pointer;
  transition: background-color 140ms ease-out, border-color 140ms ease-out;
}
#root#root .shell .mc-gs-recipe-run:hover:not(:disabled) { color: var(--mc-text); border-color: var(--mc-border-strong); background: var(--mc-surface-3); }
#root#root .shell .mc-gs-recipe-run:disabled { opacity: .45; box-shadow: none; cursor: default; }
#root#root .shell .mc-gs-recipe.tone-crit .mc-gs-recipe-run:not(:disabled) {
  color: var(--mc-danger);
  border-color: color-mix(in srgb, var(--mc-danger) 36%, transparent);
  background: var(--mc-danger-soft);
}

#root#root .shell .mc-gs-recipe-note {
  display: flex; flex-direction: column; align-items: flex-start; gap: 5px;
  padding: 12px;
  color: var(--mc-text-muted);
  background: color-mix(in srgb, var(--mc-void) 40%, transparent);
  border: 1px dashed var(--mc-border);
  border-radius: var(--mc-radius-sm);
  font-size: 11.5px;
}
#root#root .shell .mc-gs-recipe-note.is-error { border-style: solid; border-color: color-mix(in srgb, var(--mc-danger) 30%, var(--mc-border)); }
#root#root .shell .mc-gs-recipe-note strong { color: var(--mc-text); font-size: 12.5px; font-weight: 600; }
#root#root .shell .mc-gs-recipe-note.is-error strong { color: var(--mc-danger); }
#root#root .shell .mc-gs-recipe-note span { line-height: 1.45; }
#root#root .shell .mc-gs-recipe-note button {
  margin-top: 3px; min-height: 27px; padding: 0 11px;
  color: var(--mc-text-soft); background: var(--mc-surface-3);
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-sm);
  box-shadow: var(--mc-raise-1);
  font-size: 11px; cursor: pointer;
}
#root#root .shell .mc-gs-recipe-more { display: flex; }
#root#root .shell .mc-gs-recipe-more button {
  padding: 3px 0;
  color: var(--mc-text-muted); background: transparent; border: 0;
  font-size: 11px; cursor: pointer;
}
#root#root .shell .mc-gs-recipe-more button:hover { color: var(--mc-text); }

#root#root .shell .mc-ref-graph > div { display: flex; flex-wrap: wrap; gap: 6px; }
#root#root .shell .mc-ref-graph > div button {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 6px 11px;
  background: rgba(11, 14, 19, 0.6);
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-pill);
  cursor: pointer;
}
#root#root .shell .mc-ref-graph > div button:hover { border-color: var(--mc-border-strong); background: var(--mc-surface-2); }
#root#root .shell .mc-ref-graph > div button i { width: 6px; height: 6px; border-radius: 50%; background: var(--mc-text-dim); }
#root#root .shell .mc-ref-graph > div button i.ok { background: var(--mc-accent); box-shadow: 0 0 8px -1px var(--mc-accent); }
#root#root .shell .mc-ref-graph > div button i.warn { background: var(--mc-warning); box-shadow: 0 0 8px -1px var(--mc-warning); }
#root#root .shell .mc-ref-graph > div button i.crit { background: var(--mc-danger); box-shadow: 0 0 8px -1px var(--mc-danger); }
#root#root .shell .mc-ref-graph > div button code { color: var(--mc-text-soft); font-size: 11px; }

/* ------------------------------------------------------ worker inspector */

#root#root .shell .mc-gs-inspector {
  position: sticky;
  top: calc(var(--mc-gs-toolbar-clearance, 78px) + 8px);
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-sizing: border-box;
  max-height: calc(100dvh - 42px - var(--mc-gs-toolbar-clearance, 78px) - 20px);
  padding: 18px 20px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  background: rgba(17, 23, 31, 0.92) !important;
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  border: 1px solid var(--mc-border) !important;
  border-radius: 14px !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 12px 40px rgba(0, 0, 0, 0.3) !important;
}
#root#root .shell .mc-gs-inspector.state-crit { border-color: color-mix(in srgb, var(--mc-danger) 30%, var(--mc-border)) !important; }
#root#root .shell .mc-gs-inspector.state-warn { border-color: color-mix(in srgb, var(--mc-warning) 28%, var(--mc-border)) !important; }
#root#root .shell .mc-gs-inspector > header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 10px;
  margin: -2px -1px 0;
  padding: 0 1px 13px;
  border-bottom: 1px solid var(--mc-border);
}
#root#root .shell .mc-gs-inspector h2 { margin: 4px 0 5px; font-size: 16px; font-weight: 600; letter-spacing: -.02em; }
#root#root .shell .mc-gs-inspector > header code {
  display: block; overflow: hidden;
  color: var(--mc-text-dim); font-size: 11px;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-gs-inspector-close {
  flex: 0 0 auto;
  width: 25px; height: 25px;
  color: var(--mc-text-muted); background: transparent;
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-xs);
  font-size: 15px; line-height: 1; cursor: pointer;
}
#root#root .shell .mc-gs-inspector-close:hover { color: var(--mc-text); border-color: var(--mc-border-strong); background: var(--mc-surface-2); }
#root#root .shell .mc-gs-inspector-now {
  padding: 11px 12px;
  background: color-mix(in srgb, var(--mc-void) 45%, transparent);
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
}
#root#root .shell .mc-gs-inspector-now span { display: block; margin-bottom: 4px; color: var(--mc-text-dim); font-size: 9px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
#root#root .shell .mc-gs-inspector-now p { margin: 0; color: var(--mc-text-soft); font-size: 12px; line-height: 1.5; }
#root#root .shell .mc-gs-inspector-evidence { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
#root#root .shell .mc-gs-inspector-evidence small { color: var(--mc-text-dim); font-size: 9px; font-weight: 600; letter-spacing: .1em; }
#root#root .shell .mc-gs-inspector-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  background: var(--mc-border);
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
}
#root#root .shell .mc-gs-inspector-facts > div { padding: 9px 11px; background: var(--mc-surface); }
#root#root .shell .mc-gs-inspector-facts dt { color: var(--mc-text-dim); font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
#root#root .shell .mc-gs-inspector-facts dd {
  margin: 3px 0 0; overflow: hidden;
  color: var(--mc-text-soft); font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-gs-inspector-events { display: flex; flex-direction: column; gap: 6px; }
#root#root .shell .mc-gs-inspector-events article { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 9px; align-items: baseline; }
#root#root .shell .mc-gs-inspector-events time { color: var(--mc-text-dim); font-size: 10px; font-variant-numeric: tabular-nums; }
#root#root .shell .mc-gs-inspector-events span { overflow: hidden; color: var(--mc-text-muted); font-size: 11.5px; text-overflow: ellipsis; white-space: nowrap; }
#root#root .shell .mc-gs-inspector-events p { margin: 0; color: var(--mc-text-dim); font-size: 11.5px; }
#root#root .shell .mc-gs-inspector > footer {
  display: grid;
  grid-template-columns: minmax(80px, 1fr) minmax(130px, 1.4fr);
  gap: 8px;
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--mc-border);
}
#root#root .shell .mc-gs-inspector > footer button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 10px;
  color: var(--mc-text-soft);
  background: var(--mc-surface-2);
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  box-shadow: var(--mc-raise-1);
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
#root#root .shell .mc-gs-inspector > footer button:hover {
  color: var(--mc-text);
  border-color: var(--mc-border-strong);
  background: var(--mc-surface-3);
}
#root#root .shell .mc-gs-inspector > footer .mc-gs-inspector-btn--action {
  grid-column: 1;
}
#root#root .shell .mc-gs-inspector > footer .primary {
  grid-column: 2;
  color: #192128 !important;
  background: linear-gradient(#eef3f6, #d5dfe5) !important;
  border-color: #e6edf3 !important;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2), inset 0 1px 0 #fff !important;
  font-weight: 600;
}
#root#root .shell .mc-gs-inspector > footer .primary:hover {
  background: #f4f7f9 !important;
  border-color: #fff !important;
}

